قية القطع في وضعية داخل النافذة", "تكبير النافذة (يمكن تحريك أو تدوير أي قطعة)"]], ["ملاحظة", ["القطعة القاعدية أولا ثم بقية القطع"]]], "K": "للتجميع: افتح القطع، اختر أسلوب تجميع، انقل القطعة القاعدية إلى المبدأ ثم باقي القطع.", "M": ["القطعة القاعدية أولا", "ثم باقي القطع في وضعية داخل النافذة", "ثم الإجبارات"], "X": "كتركيب ألعاب «ليغو»: نضع القطعة القاعدية ثم نركّب فوقها بقية القطع.", "EX": [["ما الأسلوب المستعمل لتصميم منتج من عدة قطع؟", "أسلوب التجميع."], ["ما أول قطعة تُنقل إلى نافذة التجميع؟", "القطعة القاعدية، وتوضع عند المبدأ."]]}, {"n": 26, "m": 6, "i": "🧷", "t": "الإجبارات في التجميع", "B": [["التعريف", ["الإجبارات (مرغمات) علاقات بين سطوح أو نقاط أو خطوط القطع المختلفة", "نضغط على رمز الإجبار (Contrainte) في أداة التجميع"]], ["الخطوات", ["النقر على عنصر (سطح، خط، نقطة) في القطعة الأولى", "النقر على العنصر المناسب في القطعة الثانية", "نكرر حتى الانتهاء من جميع القطع"]], ["الأدوار", ["تثبيت القطع", "تركيب القطع بصفة جيدة", "موضع كل قطعة بالنسبة للأخرى"]]], "K": "الإجبارات تحدد وضع كل قطعة بالنسبة لأخرى بربط سطوحها أو خطوطها أو نقاطها، فتثبت القطع وتتركب جيدا.", "M": ["اختر عنصرا من القطعة الأولى ثم ما يقابله في الثانية", "كرر لكل القطع"], "X": "كالأزرار والمسامير الافتراضية: تقول للحاسوب «هذا السطح يلتصق بذاك».", "EX": [["ما دور الإجبارات؟", "تثبيت القطع وتركيبها بصفة جيدة بتحديد وضع كل قطعة بالنسبة للأخرى."], ["رتّب: فتح أسلوب التجميع، فتح القطعة الأولى، نقل القطع المتبقية.", "نفتح أسلوب التجميع، ثم القطعة الأولى (القاعدية) وننقلها، ثم ننقل القطع المتبقية."]]}, {"n": 27, "m": 7, "i": "🌐", "t": "المصطلحات التقنية (عربي – فرنسي)", "B": [["المسعى والمؤسسة", ["مسعى تكنولوجي: Démarche technologique", "مسعى المشروع: Démarche projet", "مؤسسة إنتاجية: Entreprise de production", "قيمة مضافة: Valeur ajoutée", "مواصفة: Norme ، تقييس: Normalisation", "دفتر الشروط: Cahier de charge"]], ["الرسم", ["رسم مفكك: Esquisse éclatée", "رسم تجميعي: Esquisse d'ensemble", "رسم تعريفي: Esquisse de définition", "جدول التسجيل: Cartouche ، جدول التعيينات: Nomenclature", "مقياس: Echelle", "إسقاط عمودي: Projection orthogonale"]], ["الإعلام الآلي", ["تصميم مدعم بالإعلام الآلي: Conception assistée par ordinateur", "شجرة الإنشاء: Arbre de création", "تجسيم: Extrusion ، تحديب: Bossage", "تجميع: Assemblage ، نموذج خيالي: Modèle virtuel", "مساقط معتادة: Vues ، مستوى العمل: Plan de travail"]]], "K": "تعلّم المصطلحات بالعربية والفرنسية: كثير منها يظهر في أسماء الأدوات والواجهات في البرمجيات.", "M": ["اربط كل مصطلح عربي بمقابله الفرنسي", "ركّز على: مقياس، تجميع، تجسيم، جدول التعيينات"], "X": "مثل قاموس جيب لمهندس: تحتاجه لقراءة الواجهة الفرنسية للبرمجية.", "EX": [["ما مقابل «جدول التعيينات» بالفرنسية؟", "Nomenclature."], ["ما مقابل Échelle و Assemblage؟", "مقياس (سلم) وتجميع."]]}, {"n": 28, "m": 7, "i": "🧩", "t": "الوضعيات المدرسية الممكن معالجتها", "B": [["الوضعيات 1-2", ["من منتجات المحيط: التعرف على مراحل سيرورة إنتاجها والوسائل المسخرة ومدى مطابقتها للمواصفات المحلية والدولية", "من وثائق تقنية: التعرف على الرسوم التقنية وعناصر التمثيل البياني الموحد"]], ["الوضعيات 3-4", ["من رسم منظوري: تمثيل ثنائي الأبعاد بالأدوات الاعتيادية للرسم", "من تمثيل ثنائي الأبعاد غير كامل: تحديد شكل منتج باستكمال المساقط"]], ["الوضعيات 5-7", ["اختيار أسلوب العمل (قطعة، تجميع، ثنائي الأبعاد) وتخصيص الواجهة", "تصميم نموذج خيالي ثلاثي الأبعاد لقطعة ثم إصدار تمثيلها", "تجميع نماذج القطع وإصدار تمثيل ثنائي الأبعاد وفق أسلوب عملي"]]], "K": "الوضعيات المدرسية سبع: من منتج إلى مواصفات، من وثائق إلى رسوم، من منظور إلى مساقط، ومن حاسوب إلى تصميم وتجميع.", "M": ["اقرأ نص الوضعية وحدد المطلوب: رسم يدوي أم برمجية؟", "ثم اتبع مراحل الأسلوب المناسب"], "X": "هذه خريطة ما يمكن أن يُطلب منك في التمارين: كل وضعية تتدرب فيها على جزء من الدرس.", "EX": [["ما الوضعية التي نستعمل فيها الأدوات الاعتيادية للرسم؟", "إنجاز تمثيل ثنائي الأبعاد انطلاقا من رسم منظوري."], ["ما الوضعية التي تتطلب أسلوب التجميع؟", "تجميع نماذج خيالية لقطع منتج وإصدار تمثيل ثنائي الأبعاد له."]]}];
